package com.praveen.order.controller; import com.praveen.order.model.Order; import com.praveen.order.service.OrderService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/orders") public class OrderController {private final OrderService service; public OrderController(OrderService service){this.service=service;} @GetMapping public List<Order> all(){return service.all();} @PostMapping public ResponseEntity<Order> create(@RequestBody Order o){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(o));}}
